class Solution {
public:
    int removeElement(vector<int>& nums, int val) {
        int reader=0, writer=0;
        // reader pointer will move forward in every iteration, writer will stop if nums[writer]==val, and will be overwritten by nums[reader]
        while(reader<nums.size()){
            if(nums[reader]==val){
                reader++;
            }
            else{
                nums[writer++] = nums[reader++];

            }
        }
        return writer;
    }
};,45,https://leetcode.com/problems/remove-element,https://leetcode.com/problems/remove-element/solutions/4379234/using-two-pointers-beats-100-c-clean-code/

class Solution {
    public boolean isValidSudoku(char[][] board) {
        for(int i=0; i<9; i++){
            for(int j=0; j<9; j++){
                char c = board[i][j];
                if( c >='0' && c <= '9' && !isValid(board, i, j)) return false; 
            }
        }
        return true;
    }

    private boolean isValid(char[][] board, int r, int c){
        for(int i=0; i<9; i++){
            if(r!=i && board[i][c] == board[r][c]) return false; // checking column
            if(c!=i && board[r][i] == board[r][c]) return false; // checking row
        }

        //Checking for 3x3 box
        int rowStart = 3 * (r/3); 
        int colStart = 3 * (c/3);

        for(int i=rowStart; i<rowStart + 3; i++){
            for( int j = colStart; j<colStart + 3; j++){
                if(i!=r && j!=c && board[i][j] == board[r][c]) return false; 
            }
        }

        return true;
    }
