class Solution {

    /*
        Time Complexity : O(n!)
        Space Complexity : O(n^2) + O(2*n) + O(n)
    */

private:
    vector<int> upperLeftDiagnal;
    vector<int> upperRightDiagnal;
    vector<int> upperCol;

    int res = 0;
    vector<string> board;

    void helper(int row, int size){
        if(row == size){
            res++;
            return;
        }

        for(int col=0; col<size; col++){
            if(upperCol[col]==0 and
               upperLeftDiagnal[row+col]==0 and
               upperRightDiagnal[(size-1)+col-row]==0
              ){
                board[row][col] = 'Q';
                upperCol[col] = upperLeftDiagnal[row+col] = upperRightDiagnal[(size-1)+col-row] = 1;
                helper(row+1, size);
                upperCol[col] = upperLeftDiagnal[row+col] = upperRightDiagnal[(size-1)+col-row] = 0;
                board[row][col] = '.';
            }
        }
    }

public:
    int totalNQueens(int n) {
        upperLeftDiagnal.resize(2*n-1, 0);
        upperRightDiagnal.resize(2*n-1, 0);
        upperCol.resize(n, 0);

        board.resize(n);
        string s(n, '.');

        for(int i=0; i<n; i++){
            board[i] = s;
        }

        //row, size
        helper(0, n);

        return res;
    }
};,68,https://leetcode.com/problems/n-queens-ii,https://leetcode.com/problems/n-queens-ii/solutions/3481133/c-using-recursion-backtracking-t-c-o-n-s-c-o-n-2/

class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        vector<vector<int>> dp(2, vector<int>(size(nums)));
        dp[0][0] = dp[1][0] = nums[0];
        for(int i = 1; i < size(nums); i++) {
            dp[1][i] = max(nums[i], nums[i] + dp[1][i-1]);
            dp[0][i] = max(dp[0][i-1], dp[1][i]);
        }
        return dp[0].back();
    }
};,63,https://leetcode.com/problems/maximum-subarray,https://leetcode.com/problems/maximum-subarray/solutions/1595195/c-python-7-simple-solutions-w-explanation-brute-force-dp-kadane-divide-conquer/

