class Solution {
public:
    string getPermutation(int n, int k) {
        vector <int> nums;
        int fact = 1;
        for (int i = 1; i <= n; i++) {
            nums.push_back(i);
            fact *= i;
        }
        k--;
        string ans = "";
        while (n != 0) {
            fact /= n;
            int ind = k / fact;
            k -= ind * fact;
            ans += to_string(nums[ind]);
            nums.erase(nums.begin() + ind);
            n--;
        }
        return ans;
    }
};,24,https://leetcode.com/problems/permutation-sequence,https://leetcode.com/problems/permutation-sequence/solutions/3954305/best-o-n-n-solution/

class Solution {
    public int minPathSum(int[][] grid) {
        int n=grid[0].length, dp[][]=new int[2][n], m=grid.length, i, inf=88000;
        for(i=0; i<m; ++i) 
            for(int j=0; j<n; ++j) 
                if(i==0 && j==0) dp[(i)%2][j]=grid[i][j];
                else dp[i&1][j]=grid[i][j]+Math.min(i==0?inf:dp[(i-1)&1][j], 
                                                    j==0?inf:dp[i&1][j-1]);
        return dp[(i-1)&1][n-1];
    }
