class Solution {
public:
    bool isNumber(string S) {
        bool num = false, exp = false, sign = false, dec = false;
        for (auto c : S)
            if (c >= '0' && c <= '9') num = true ;    
            else if (c == 'e' || c == 'E')
                if (exp || !num) return false;
                else exp = true, sign = false, num = false, dec = false;
            else if (c == '+' || c == '-')
                if (sign || num || dec) return false;
                else sign = true;
            else if (c == '.')
                if (dec || exp) return false;
                else dec = true;
            else return false;
        return num;
    }
};,34,https://leetcode.com/problems/valid-number,https://leetcode.com/problems/valid-number/solutions/1209315/js-python-java-c-easy-character-conditional-solution-w-explanation/

class Solution {
public:
    string addBinary(string a, string b) {
        int alen = a.length();
        int blen = b.length();
        int i =0, carry=0;
        string ans ="";
        while(i<alen || i<blen || carry!=0){
            int x =0;
            if(i<alen && a[alen-i-1] == '1'){
                x=1;
            }
            int y =0;
            if(i<blen and b[blen-i-1] =='1'){
                y =1;
            }
            ans = to_string((x+y+carry)%2)+ans;
            carry= (x+y+carry)/2;
            i+=1;

        }
        return ans;
    }
};,71,https://leetcode.com/problems/add-binary,https://leetcode.com/problems/add-binary/solutions/4050544/add-binary-c-solution/

class Solution {
public:
    vector<string> fullJustify(vector<string>& words, int maxWidth) {
        // Intution
        // The idea in here is really very simple. What we will do is we will maintain the spaces required for the words in the temporary vector and also the number of characters in the current word. If we found that the total lenght is greater than or equal to maximum length then we will perform the operation.

        int spacesReq;
        int currLen = 0;

        vector<string> temp;
        vector<string> result;

        for(auto &word : words){
            int wordLen = word.size();
            spacesReq = temp.size();
            if(currLen + wordLen + spacesReq > maxWidth){
                string answer = "";
                int spaces = maxWidth - currLen;
                if(temp.size() == 1){
                    answer = temp[0];
                    while(spaces --> 0) answer += " ";
                    result.push_back(answer);
                }
                else{
                    int spaceBetween = spaces / (temp.size() - 1);
                    int extraSpaces = maxWidth - currLen - spaceBetween * (temp.size() - 1);
                    answer = temp[0];
                    string bet = "";
                    while(spaceBetween --> 0) bet += " ";
                    for(int i = 1 ; i < temp.size() ; i++){
                        answer += bet;
                        if(extraSpaces > 0){
                            answer += " ";
                            extraSpaces -= 1;
                        }
                        answer += temp[i];
                    }
                    result.push_back(answer);
                }
                temp.clear();
                currLen = wordLen;
                temp.push_back(word);
            }
            else{
                currLen += wordLen;
                temp.push_back(word);
            }
        }

        if(temp.size() >= 1){
            string answer = temp[0];
            for(int i = 1 ; i < temp.size() ; i++){
                answer += " " + temp[i];
            }
            while(answer.size() < maxWidth) answer += " ";
            result.push_back(answer);
        }

        return result;

    }
};,89,https://leetcode.com/problems/text-justification,https://leetcode.com/problems/text-justification/solutions/3952495/c-easy-solution-faster-than-100-excellent-code/

class Solution {
public:
    int minDistance(string x, string y) {
        int m = x.size(), n = y.size();
        int dp[m+1][n+1];
        memset(dp, 0, sizeof(dp));
        for(int i=1; i<=m; i++) dp[i][0] = i;
        for(int j=1; j<=n; j++) dp[0][j] = j;
        for(int i=1; i<=m; i++){
            for(int j=1; j<=n; j++){
                dp[i][j] = (x[i-1] == y[j-1]) ? dp[i-1][j-1] : 1 + min(dp[i-1][j-1], min(dp[i][j-1], dp[i-1][j]));
            }
        }
        return dp[m][n];
    }
};,93,https://leetcode.com/problems/edit-distance,https://leetcode.com/problems/edit-distance/solutions/3246536/simple-c-code/

class Solution {
public:
    void setZeroes(vector<vector<int>>& matrix) {
        int m = matrix.size(), n = matrix[0].size();
        unordered_map<int, bool> rowMap;
        unordered_map<int, bool> colMap;

        for(int i=0; i<m; i++){
            for(int j=0; j<n; j++){
                if(matrix[i][j] == 0){
                    rowMap[i] = true;
                    colMap[j] = true;
                }
            }
