class Solution {
public:
    bool solve(string s1, string s2,unordered_map<string, bool> &mp)
    {
        if(s1.length()==1)
            return s1==s2;
        if(s1==s2)
            return true;

        if(mp.find(s1+s2)!=mp.end())
            return mp[s1+s2];

        int n = s1.length();
        for(int i=1;i<n;i++)
        {
            if((solve(s1.substr(0,i),s2.substr(0,i),mp) and solve(s1.substr(i),s2.substr(i),mp)) or (solve(s1.substr(0,i),s2.substr(n-i),mp) and solve(s1.substr(i),s2.substr(0,n-i),mp)) )
                return mp[s1+s2] = true;

        }

        return mp[s1+s2] = false;

    }


    bool isScramble(string s1, string s2) {
        unordered_map<string, bool> mp;
        return solve(s1,s2,mp);


    }
