class Solution {
public:
    string shortestPalindrome(string t) {
	    reverse(all(t));

        string rev = t;
	    reverse(all(rev));
	    string s = rev + '#' + t; // palindrome that needs to be added
        int n = s.size();
        vector<int> kmpp(n + 1);
        kmpp[0] = -1;
        int i = 0 , j = -1 ;
        while (i < n) {
            while (j > 0 && s[i] != s[j]) j = kmpp[j];
            j++;
            i++;
            kmpp[i] = j;
        }

        int req = t.size()-kmpp[n];
        string add ="";
        for(int i = 0 ;i < req ;i ++){
            add+=t[i];
        }

        reverse(all(t));
        return add+t;
    }
