class Solution {
public:
    string toPostfix(string& s) {
        auto precedence = [](char c){return c == '*' || c == '/';};
        stack<char> op;
        string post = "";
        for(auto c : s) 
            if(c == ' ') continue;
            else if(isdigit(c)) post += c;
            else {
                post += '|';                              // markers to separate numbers
                while(size(op) && precedence(c) <= precedence(op.top())) 
                    post += op.top(), op.pop();
                op.push(c);
            }

        post += '|';
        while(size(op)) 
            post += op.top(), op.pop();        
        return post;
    }
    int calculate(string& s) {
        s = toPostfix(s);
        stack<int> num;
        for(int i = 0; i < size(s); i++) 
            if(isdigit(s[i])) {
                int cur = 0;
                while(i < size(s) && isdigit(s[i]))
                    cur = cur * 10 + (s[i++] - '0');
                num.push(cur);
            }
            else {
                int num1 = num.top(); num.pop();
                int num2 = num.top(); num.pop();
                if(s[i] == '*')      num.push(num2 * num1);
                else if(s[i] == '/') num.push(num2 / num1);
                else if(s[i] == '+') num.push(num2 + num1);
                else if(s[i] == '-') num.push(num2 - num1);
            }

        return num.top();
    }
};,63,https://leetcode.com/problems/basic-calculator-ii,https://leetcode.com/problems/basic-calculator-ii/solutions/1646099/c-python-simple-solutions-w-explanation-postfix-stack-without-stack/

class Solution {
public:
    int calculate(string& s) {
        int cur = 0, ans = 0, interimRes = 0;
        char prevOp = '+';
        s += "##";                                     // just ensures all processing happens in loop...else we need to write outside for the last number
        for(auto c : s)
            if(c == ' ') continue;
            else if(isdigit(c)) 
                cur = cur * 10 + (c-'0');
            else {
                if(prevOp == '*')                      // '*':  Case-1
                    interimRes *= cur;
                else if(prevOp == '/')                 // '/':  Case-1
                    interimRes /= cur;
                else                                   // '+' and '-':  Case-2
                    ans += interimRes,
                    interimRes = prevOp == '+' ? cur : -cur;
                prevOp = c;
                cur = 0;
            }

        return ans;
    }
