class Solution {
public:

    // sort the array on the basis of heights in decreasing order

    static bool compare(vector<int>& a, vector<int>& b)
    {
        if(a[0] == b[0])
        {
            return a[1] < b[1];
        }
        else
            return a[0] > b[0];
    }

    vector<vector<int>> reconstructQueue(vector<vector<int>>& people) {

        int n = people.size();

        // sort the people array

        sort(people.begin(), people.end(), compare);

        // res is reconstructed array

        vector<vector<int>> res;

        for(int i = 0; i < n; i++)
        {
            // place the curr people in its correct position

            int pos = people[i][1];

            res.insert(res.begin() + pos, people[i]);
        }

        return res;
    }
