    int ans = -1;
    while (lb <= ub)
    {
        int mid = lb + (ub - lb) / 2;
        if (isValid(mid, houses, heaters))
        {
            ans = mid;
            ub = mid - 1;
        }
        else
        {
            lb = mid + 1;
        }
    }
    return ans;
}

