 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int findBottomLeftValue(TreeNode* root) {
        queue<pair<TreeNode*,int>> q;
        int ans;
        int maxl = -1;
        q.push({root,0});

        while(!q.empty()){
            pair<TreeNode*,int> t = q.front();
            q.pop();

            TreeNode* node = t.first;
            int l = t.second;

            if(l > maxl){
                maxl = l;
                ans = node->val;
            }

            if(node->left){
                q.push({node->left,l+1});
            }
            if(node->right){
                q.push({node->right,l+1});
            }
        }
        return ans;
    }
};,54,https://leetcode.com/problems/find-bottom-left-tree-value,https://leetcode.com/problems/find-bottom-left-tree-value/solutions/3933569/easy-c-solution-using-queue/

class Solution {
public:
    using VI = vector<int>;
    int findRotateSteps(string ring, string key, int INF = 1e9 + 7) {
        int M = ring.size(),
            N = key.size();
        auto steps = [=](auto i, auto k) {
            return min(abs(i - k), M - abs(i - k)); // ⭐️ minimum of steps to rotate the ring from i..k (🚫 without wrap-around, ✅ with wrap-around)
        };
        VI pre(M); // 🤔 memo + 🛑 base case (ie. pre is default initialized to contain all 0s)
        for (auto j{ N - 1 }; 0 <= j; --j) {  // key j
            VI cur(M, INF);
            for (auto i{ 0 }; i < M; ++i)     // cur i
                for (auto k{ 0 }; k < M; ++k) // pre i (optimal k-th value is found as the recursive stack unwinds)
                    if (ring[k] == key[j])
                        cur[i] = min(cur[i], 1 + steps(i, k) + pre[k]); // 🎯 min steps to reach key[j] from each ring[i] is the min steps to reach key[j + 1] from ring[k], 🔍 find optimal k via exhaustive search
            swap(pre, cur);
        }
        return pre[0]; // 🚀 when the ring starts at i = 0 (ie. index 0 is aligned with the 12:00 direction of the ring) return the min steps to construct key[j = 0..N - 1]
    }
};,177,https://leetcode.com/problems/freedom-trail,https://leetcode.com/problems/freedom-trail/solutions/1147789/the-art-of-dynamic-programming/

class Solution {
    public List<Integer> largestValues(TreeNode root) {
        Queue<TreeNode> queue = new LinkedList<>();
        List<Integer> ans = new ArrayList<>();
        queue.offer(root);
        if(root==null)  return ans;
        while(!queue.isEmpty())
        {
            int level = queue.size();
            int max = Integer.MIN_VALUE;
            for(int i=0;i<level;i++)
            {
                TreeNode temp =queue.poll();
                if(temp.left!=null)
                {
                    queue.offer(temp.left);
                }
                if(temp.right!=null)
                {
                    queue.offer(temp.right);
                }
                max= Math.max(max, temp.val);
            }
            ans.add(max);
        }
        return ans;
    }
