class Solution {
public:
    bool seen[16] = {};
    int res = 0;
    int countArrangement(int n, int pos = 1) {
        if (n < 4) return n;
        if (pos > n) return res++;
        for (int i = 1; i <= n; i++) {
            if (!seen[i] && (i % pos == 0 || pos % i == 0)) {
                // marking i as seen
                seen[i] = true;
                countArrangement(n, pos + 1);
                // backtracking
                seen[i] = false;
            }
        }
        return res;
    }
