class Solution {
public:
#define mod 1000000007
    int solve(int row, int col, int count, int n, int m, vector<vector<vector<int>>> &dp)
    {
        if(row <0 or row >= n or col < 0 or col >= m)
        {
            return 1;
        }

        if(count == 0)
        {
            return 0;
        }

        if(dp[row][col][count] != -1)
        {
            return dp[row][col][count];
        }

        int rr[] = {-1, 0, 1, 0};
        int cc[] = {0, 1, 0, -1};

        int ans = 0;
        for(int i = 0; i < 4; i++)
        {
            int r = row + rr[i];
            int c = col + cc[i];
            ans += solve(r, c, count - 1, n, m, dp);
            ans %= mod;
        }
        return dp[row][col][count] = ans % mod;
    }

    int findPaths(int n, int m, int maxMove, int startRow, int startColumn) 
    {
        vector<vector<vector<int>>> dp(n, vector<vector<int>>(m, vector<int>(maxMove + 1, -1)));
        return solve(startRow, startColumn, maxMove, n, m, dp);
    }
