class Solution {
    /*
        10101

zero    1   2   3   5   8
one     1   1   2   3   5
        0   1   2   3   4

        0xxxx   => i => [1]0101, add 0xxxx / zero[i] to answer, because 0xxxx contains all combinations which smaller than 1xxxx
        100xx  => i => 10[1]01, add 100xx / zero[i] to answer, because 100xx contains all combinations which smaller than 101xx
        1010x  => i => 1010[1], add 10100 / zero[i] to answer, 10100 smaller than 10101
        10101 => this is the extra 1 in final return.

    */
    public int findIntegers(int n) {
        int[] zero = new int[31];
        int[] one = new int[31];
        zero[0] = one[0] = 1;
        for(int i = 1; i < 31; i++) {
            zero[i] = zero[i - 1] + one[i - 1];
            one[i] = zero[i - 1];
        }
        int ans = 0;
        int preBit = -1;
        for(int i = 30; i >= 0; i--) {
            int bit = (n & (1 << i)) == 0 ? 0 : 1;
            if(bit == 1) {
                ans += zero[i];
                if(preBit == 1) {
                    return ans;
                }
            }
            preBit = bit;
        }
        return ans + 1;
    }
