class Solution {
public:
    int findLongestChain(vector<vector<int>>& pairs) {
        //-1000 <= lefti < righti <= 1000
        vector<int> left(2002, INT_MIN);
        for(auto& p: pairs){
            int l=p[0]+1000;//l=left-1+1001
            int r=p[1]+1001;//r=right+1001
            //Many pairs with same right. Take the biggest one 
            left[r]=max(left[r], l);
        }
        // dp[right]=# of chaining pairs (l,r] with r<=right
        vector<int> dp(2002, 0);
        for (int i=1; i<=2001; i++) {
            dp[i] = dp[i-1];
            if (left[i]!=INT_MIN) 
                dp[i] = max(dp[i], 1+dp[left[i]]);
        }
        return dp[2001];
    }
};

