class Solution {
public:
    vector<vector<int>> imageSmoother(vector<vector<int>>& img) {
        // Save the dimensions of the image.
        int m = img.size(); // Number of rows
        int n = img[0].size(); // Number of columns

        // Iterate over the cells of the image.
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                // Initialize the sum and count for averaging.
                int sum = 0;
                int count = 0;

                // Iterate over all plausible nine indices around the current cell.
                for (int x = i - 1; x <= i + 1; x++) {
                    for (int y = j - 1; y <= j + 1; y++) {
                        // If the indices form a valid neighbor within the image boundaries.
                        if (0 <= x && x < m && 0 <= y && y < n) {
                            // Extract the original value of img[x][y] using bitwise AND operation with 255.
                            sum += img[x][y] & 255; // Extracting the last 8 bits (0-255 range)
                            count += 1;
                        }
                    }
                }

                // Encode the smoothed value in img[i][j].
                img[i][j] |= (sum / count) << 8; // Storing the average in the next 8 bits (8-16) of img[i][j]
            }
        }

        // Extract the smoothed value from the encoded img[i][j] using bitwise right shift.
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                img[i][j] >>= 8; // Shift 8 bits to the right to extract the average value
            }
        }

        // Return the smooth image.
        return img;
    }
};




