class Solution {
public:
    int DFS(TreeNode*root,int &max_len){
        if(!root)return max_len;
        int lh=DFS(root->left,max_len);
        int rh=DFS(root->right,max_len);
        if(!root->left || root->left->val!=root->val)lh=0;
        if(!root->right || root->right->val!=root->val)rh=0;
        max_len=max(max_len,lh+rh);
        return 1+max(lh,rh);

    }
    int longestUnivaluePath(TreeNode* root) {
        //path can start from any node & can have maximum value left height+right height where root->val==each value in that path like the case[5,5,5,5,1,null,5] 
        int res=INT_MIN;
        DFS(root,res);
        return res!=INT_MIN?res:0;

    }
};,167,https://leetcode.com/problems/longest-univalue-path,https://leetcode.com/problems/longest-univalue-path/solutions/3045413/simple-dfs-solution-beats-92-o-n-time/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int longestUnivaluePath(TreeNode* root) 
{
     //code
     int ans=0;
     pair<int,int>x=fun(root,ans);
        if(ans==0)
            return 0;
     return ans-1;
}
pair<int,int> fun(TreeNode* root,int &ans)
{
	if(root==NULL)
	{
		//code
		return make_pair(-6000,0);
	}
	pair<int,int>left=fun(root->left,ans);   //<val,height>
	pair<int,int>right=fun(root->right,ans); //<val,height>

	if(root!=NULL and root->val==left.first and root->val==right.first)
	{
		ans=max(ans,(left.second+right.second+1));
		return make_pair(root->val,max(left.second,right.second)+1);
	}
	else if(root!=NULL and root->val==left.first and root->val!=right.first)
	{
		ans=max(ans,left.second+1);
		return make_pair(root->val,left.second+1);
	}
	else if(root!=NULL and root->val!=left.first and root->val==right.first)
	{
		ans=max(ans,right.second+1);
		return make_pair(root->val,right.second+1);
	}
	else if(root!=NULL and root->val!=left.first and root->val!=right.first)
	{
		ans=max(ans,1);
		return make_pair(root->val,1);
	}
	return make_pair(-1,-1);  //this wil never get encountered
}
