class Solution {
public:
    int maxAreaOfIsland(vector<vector<int>>& grid) {
        int result = 0, n = grid.size(), m = grid[0].size();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 1)
                    result = max(result, bfs(grid, i, j, n, m));
            }
        }

        return result;
    }

private:
    int bfs(vector<vector<int>>& grid, int r, int c, int& n, int& m) {
        int result = 0;

        queue<pair<int,int>> Q;
        grid[r][c] = -1; // mark as visited
        Q.emplace(r, c);

        while (!Q.empty()) {
            auto [r, c] = Q.front(); Q.pop();
            result++;

            int DIR[][2] = { {0, -1}, {1, 0}, {0, 1}, {-1, 0} }; // left, up, right, down

            for (int i = 0; i < 4; i++) {
                int nr = r + DIR[i][0], nc = c + DIR[i][1];
                if (nr < 0 || nc < 0 || nr >= n || nc >= m || grid[nr][nc] != 1)
                    continue;
                grid[nr][nc] = -1; // mark as visited
                Q.emplace(nr, nc);
            }

        }

        return result;
    }
};,119,https://leetcode.com/problems/max-area-of-island,https://leetcode.com/problems/max-area-of-island/solutions/3852216/c-bfs-clean-solution/

class Solution {
    public int search(int[] nums, int target) {
        int start = 0, end = nums.length-1;
        while(start<= end)
        {
           int mid = (start+end)/2;
           if(nums[mid] == target)
           {
              return mid;
           }
           if(nums[mid]>target)
           {
               end = mid-1;
           }
            else
            {
               start = mid+1;
            }
        }
        return -1;
    }
