class Solution {
public:
    int maxProfit(vector<int>& prices, int fee) {
        int n = prices.size();
        int currBuy, currDontBuy, nextSell, nextDontSell;

        nextSell = nextDontSell = 0; // base case

        /*
            next[1] -> nextSell
            next[0] -> nextDontSell

            curr[1] -> currBuy
            curr[0] -> currDontBuy
        */

        for (int i=n-1; i>=0; i--) {
            currBuy = max(nextDontSell - prices[i] - fee, nextSell);
            currDontBuy = max(nextSell + prices[i], nextDontSell);

            nextSell = currBuy;
            nextDontSell = currDontBuy;
        }

        return nextSell;
    }
};,135,https://leetcode.com/problems/best-time-to-buy-and-sell-stock-with-transaction-fee,https://leetcode.com/problems/best-time-to-buy-and-sell-stock-with-transaction-fee/solutions/3682835/brute-force-optimal-solution/

class Solution {
public:
    int findLength(vector<int>& nums1, vector<int>& nums2) {

        int n1 = nums1.size();

        int n2 = nums2.size();

        // declare a dp

        vector<vector<int>> dp(n1 + 1, vector<int> (n2 + 1, 0));

        int maxi = 0;

        // fill dp

        for(int i = 0; i <= n1; i++)
        {
            for(int j = 0; j <= n2; j++)
            {
                // base case

                if(i == 0 || j == 0)
                {
                    dp[i][j] = 0;
                }
                else
                {
                    if(nums1[i - 1] == nums2[j - 1])
                    {
                        dp[i][j] = 1 + dp[i - 1][j - 1];
                    }
                    else
                    {
                        dp[i][j] = 0;
                    }
                }

                // update maxi

                maxi = max(maxi, dp[i][j]);
            }
        }

        return maxi;
    }
};,23,https://leetcode.com/problems/maximum-length-of-repeated-subarray,https://leetcode.com/problems/maximum-length-of-repeated-subarray/solutions/2599363/faster-easy-to-understand-c-code/

class Solution {
public:
    int smallestDistancePair(vector<int>& v, int k) {
        sort(v.begin(),v.end());
        int mn = 0,mx = v[v.size()-1]-v[0],mid,x,i,j,n=v.size();
        while(mn<mx){
            mid = (mx-mn)/2+mn;
            i = 0, j = 0,x = 0;
            while(i<n){
                while((j<n)&&(v[j]-v[i]<=mid)){
                    j++;
                }
                x += (j-i-1);
                i++;
            }
            if(x>=k){
                mx = mid;
            }else{
                mn = mid+1;
            }
        }
        return mn;
    }
