class Solution {

    public int maxDistToClosest(int[] seat) {

        ArrayList<Integer> arr = new ArrayList<>();
        int ans = 0;

        for(int i=0; i<seat.length; i++){
            if(seat[i]==1) arr.add(i);
        }

        if(arr.size()==1){
            int a = arr.get(0);
            if(a==0 || a==seat.length-1) return seat.length-1;
            else{
                int x = seat.length-a-1;
                int y = a;
                return Math.max(x,y);
            }
        }

        for(int i=0; i<arr.size()-1; i++){
            int diff = arr.get(i+1)-arr.get(i);
            ans = Math.max(ans,diff/2);
        }

        int a = arr.get(0);
        int b = arr.get(arr.size()-1);

        if(a>ans) ans = a;
        if(seat.length-1-b>ans) ans = seat.length-1-b;
        return ans;
    }
