class Solution:
    def rectangleArea(self, rectangles):
        ys = sorted(set([y for x1, y1, x2, y2 in rectangles for y in [y1, y2]]))
        y_i = {v: i for i, v in enumerate(ys)}
        count = [0] * len(y_i)

        sides_lft = [(x1,-1,y1,y2) for x1,y1,x2,y2 in rectangles]
        sides_rgh = [(x2,1,y1,y2) for x1,y1,x2,y2 in rectangles]
        sides = sorted(sides_lft + sides_rgh)

        cur_x = cur_y_sum = area = 0
        for x, op_cl, y1, y2 in sides:
            area += (x - cur_x) * cur_y_sum
            cur_x = x
            for i in range(y_i[y1], y_i[y2]):
                count[i] += op_cl
            cur_y_sum = sum(y2 - y1 if c else 0 for y1, y2, c in zip(ys, ys[1:], count))
        return area % (10 ** 9 + 7),106,https://leetcode.com/problems/rectangle-area-ii,https://leetcode.com/problems/rectangle-area-ii/solutions/1419181/python-4-solutions-n-3-n-2-log-n-n-2-n-log-n-explained/

class Solution {
    class Point {
        int x, y, val;
        Point(int x, int y, int val) {
            this.x = x;
            this.y = y;
            this.val = val;
        }
    }
    public int rectangleArea(int[][] rectangles) {
        int M = 1000000007;
        List<Point> data = new ArrayList<>();
        for (int[] r : rectangles) {
            data.add(new Point(r[0], r[1], 1));
            data.add(new Point(r[0], r[3], -1));
            data.add(new Point(r[2], r[1], -1));
            data.add(new Point(r[2], r[3], 1));
        }
        Collections.sort(data, (a, b) -> {
            if (a.x == b.x) {
                return b.y - a.y;
            }
            return a.x - b.x;
        });
        TreeMap<Integer, Integer> map = new TreeMap<>();
        int preX = -1;
        int preY = -1;
        int result = 0;
        for (int i = 0; i < data.size(); i++) {
            Point p = data.get(i);
            map.put(p.y, map.getOrDefault(p.y, 0) + p.val);
            if (i == data.size() - 1 || data.get(i + 1).x > p.x) {
                if (preX > -1) {
                    result += ((long)preY * (p.x - preX)) % M;
                    result %= M;
                }
                preY = calcY(map);
                preX = p.x;
            }
        }
        return result;
    }
    private int calcY(TreeMap<Integer, Integer> map) {
        int result = 0, pre = -1, count = 0;
        for (Map.Entry<Integer, Integer> e : map.entrySet()) {
            if (pre >= 0 && count > 0) {
                result += e.getKey() - pre;
            }
            count += e.getValue();
            pre = e.getKey();
        }
        return result;
    }
