class Solution {
public:
    int binaryGap(int n) {
        int count=0;
        int c=0;
        while(n>0){
            if(n%2==0){
                if(count>0){
                    count++;
                }
                c=max(c,count);
                n=n/2;
            }
            else{
                c=max(c,count);
                count=1;
                n=n/2;
            }
        }
        return c;
    }
