class Solution {
    public int superEggDrop(int K, int N) {
        int[][] memo = new int[K + 1][N + 1];
        return helper(K, N, memo);
    }
    private int helper(int K, int N, int[][] memo) {
        if (N <= 1) {
            return N;
        }
        if (K == 1) {
            return N;
        }
        if (memo[K][N] > 0) {
            return memo[K][N];
        }

        int low = 1, high = N, result = N;
        while (low < high) {
            int mid = low + (high - low) / 2;
            int left = helper(K - 1, mid - 1, memo);
            int right = helper(K, N - mid, memo);
            result = Math.min(result, Math.max(left, right) + 1);
            if (left == right) {
                break;
            } else if (left < right) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        memo[K][N] = result;
        return result;
    }
},175,https://leetcode.com/problems/super-egg-drop,https://leetcode.com/problems/super-egg-drop/solutions/159055/java-dp-solution-from-o-kn-2-to-o-knlogn/

class Solution {
public:
    vector<string> findAndReplacePattern(vector<string>& words, string pattern) {
        int i, j, flag=0;
        vector<string> ans;
        unordered_map<char, char> m;

        for(i=0 ; i<words.size() ; i++)
        {
            flag=0;
            for(j=0 ; j<words[i].size() ; j++)
            {
                for(auto it:m)
                {
                    if(it.first==pattern[j] && it.second!=words[i][j])
                    {
                        flag=1;
                        break;
                    }
                    if(it.second==words[i][j] && it.first!=pattern[j])
                    {
                        flag=1;
                        break;
                    }
                }

                if(flag==1)
                {
                    break;
                }
                m[pattern[j]] = words[i][j];
            }
            if(flag==0)
            {
                ans.push_back(words[i]);
            }
            m.clear();
        }
        return ans;
    }
