class RLEIterator {
public:
    RLEIterator(vector<int>& encoding) {
        rle = encoding;
        size = encoding.size();
    }

    int next(int n) {
        while (idx < size) {

            if (n <= rle[idx]) {
                rle[idx] -= n;
                return rle[idx+1];
            }

            else {
                n -= rle[idx];
                idx += 2;
            }
        }

        return -1;
    }

private:
    vector<int> rle;
    int idx = 0,size;
