class Solution {
    private int M = (int)1e9 + 7;
    public int numPermsDISequence(String S) {
        int n = S.length();
        long[][] dp = new long[n + 1][n + 1];
        int[][] nCkMemo = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            dp[i][i] = 1;
        }
        for (int len = 1; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len;
                if (S.charAt(i) == 'D') {
                    dp[i][j] += dp[i + 1][j];
                    dp[i][j] %= M;
                }
                for (int k = i + 1; k < j; k++) {
                    if (S.charAt(k - 1) == 'I' && S.charAt(k) == 'D') {
                        dp[i][j] += (((dp[i][k - 1] * dp[k + 1][j]) % M) * nCk(len, k - i, nCkMemo)) % M;
                        dp[i][j] %= M;
                    }
                }
                if (S.charAt(j - 1) == 'I') {
                    dp[i][j] += dp[i][j - 1];
                    dp[i][j] %= M;
                }
            }
        }
        return (int)dp[0][n];
    }
    private int nCk(int n, int k, int[][] nCkMemo) {
        if (k == 0 || k == n) {
            return 1;
        }
        if (nCkMemo[n][k] == 0) {
            nCkMemo[n][k] = (nCk(n - 1, k, nCkMemo) + nCk(n - 1, k - 1, nCkMemo)) % M;
        }
        return nCkMemo[n][k];
    }
},175,https://leetcode.com/problems/valid-permutations-for-di-sequence,https://leetcode.com/problems/valid-permutations-for-di-sequence/solutions/168612/top-down-with-memo-bottom-up-dp-n-3-dp-n-2-dp-o-n-space/

