public class Solution {
    public int NumMusicPlaylists(int n, int goal, int k) {
        int mod = 1000000007;
        long[,] dp = new long[n + 1, goal + 1];
        dp[0, 0] = 1;

        for (int j = 1; j <= goal; j++) {
            for (int i = 1; i <= n; i++) {
                dp[i, j] = (dp[i - 1, j - 1] * i) % mod;
                if (i > k) {
                    dp[i, j] = (dp[i, j] + (dp[i, j - 1] * (i - k)) % mod) % mod;
                }
            }
        }

        return (int)dp[n, goal];
    }
