let MOD = 10 ** 9 + 7;
var threeSumMulti = function (a, t) {
    let n = a.length;

    a.sort((a, b) => a - b);

    // i + L + R = t
    let cc = 0;
    for (let i = 0; i < n; i++) {
        let search = t - a[i]; //  L + R = t -i

        for (let L = i + 1, R = n - 1; L < R; ) {
            let search2 = a[L] + a[R]; // target;

            if (search2 === search) {
                if (a[L] !== a[R]) {
                    let ccleft = 1, // count of equal on left
                        ccright = 1; // count of equal on right
                    while (L + 1 < R && a[L] == a[L + 1]) ccleft++, L++;
                    while (R - 1 > L && a[R] == a[R - 1]) ccright++, R--;
                    cc = cc + ccleft * ccright;
                    cc = cc % MOD;
                    L++;
                    R--;
                } else {
                    let count = R - L;
                    cc = cc + (count * (count + 1)) / 2; // pairs
                    cc = cc % MOD;
                    break;
                }
            } else if (search2 < search) {
                L++;
            } else {
                R--;
            }
        }
    }

    return cc;
};,100,https://leetcode.com/problems/3sum-with-multiplicity,https://leetcode.com/problems/3sum-with-multiplicity/solutions/3306878/javascript-923-3sum-with-multiplicity/

