class Solution {
public:
    queue<pair<int, int>> Q;

    pair<int, int> find_ini_grid(int n, vector<vector<int>>& grid){      
        for (int i=0; i<n; i++)
            for(int j=0; j<n; j++)
                if (grid[i][j]==1){
                  return {i, j};  
            }
        return {-1,-1};
    }
    void print(int n, vector<vector<int>>& grid){
        for (int i=0; i<n; i++){
            for(int j=0; j<n; j++)
                cout<<setw(3)<<grid[i][j];
            cout<<endl;
        }
    }

    void find_A(int x, int y, vector<vector<int>>& grid, int n){
        if (x<0 || x>=n || y<0 || y>=n) return;
        if (grid[x][y]==1) {
            grid[x][y]=2;
            Q.push({x, y});
            find_A(x+1, y, grid, n);
            find_A(x, y+1, grid, n);
            find_A(x-1, y, grid, n);
            find_A(x, y-1, grid, n);
        }        
    }

    int shortestBridge(vector<vector<int>>& grid) {
        int n=grid.size();
        pair<int, int> P=find_ini_grid(n, grid);
        find_A(P.first, P.second,  grid, n);
        int d;
        for (d=0; ; d++){
            queue<pair<int, int>> Q2;
            while(!Q.empty()){              
                pair<int, int> P=Q.front();
                Q.pop();
                int x=P.first, y=P.second;
                vector<pair<int,int>> adj({{x+1,y},{x, y+1},{x-1, y},{x, y-1}});
                for(auto& [x2, y2]: adj)
                {
                    if (x2<0 || x2>=n || y2<0 || y2>=n) continue;
                    if (grid[x2][y2]==1) {
                  //    print(n, grid);//print the graph w dist.info
                        return d;
                    }
                    else if (grid[x2][y2]==0) {
                        Q2.push({x2,y2});
                        grid[x2][y2]=-1-d;//distance d to island A
                    }
                }    
            }          
            Q=Q2;
        }
        return d;       
    }
};,49,https://leetcode.com/problems/shortest-bridge,https://leetcode.com/problems/shortest-bridge/solutions/3546667/c-dfs-bsf-solutions-with-video-explanation-distance-info-on-the-graph/

class Solution {
public:

    int ans = INT_MAX;
    void bfs(queue<vector<int>> q, vector<vector<int>> &arr){
        vector<vector<int>> dir = {{0,1},{0,-1},{-1,0},{1,0}};
        int n = arr.size();
        int m = arr[0].size();

        while(q.size()!=0){
            vector<int> a = q.front();
            q.pop();
            int i = a[0];
            int j = a[1];

            for(int k=0; k<4; k++){
                int nr = i+dir[k][0];
                int nc = j+dir[k][1];

                if(nr>=0 && nc>=0 && nr<n && nc<m && arr[nr][nc]==1){
                    arr[nr][nc]=-1;
                    q.push({nr,nc});
                }
            }
        }
    }

    void bfs2(queue<vector<int>> q, vector<vector<int>> &arr, vector<vector<int>> visited){
        vector<vector<int>> dir = {{0,1},{0,-1},{-1,0},{1,0}};
        int n = arr.size();
        int m = arr[0].size();

        while(q.size()!=0){
            vector<int> a = q.front();
            q.pop();
            int i = a[0];
            int j = a[1];
            int step = a[2];
            visited[i][j] = 1;
            for(int k=0; k<4; k++){
                int nr = i+dir[k][0];
                int nc = j+dir[k][1];
                if(nr>=0 && nc>=0 && nr<n && nc<m && visited[nr][nc]==0){

                    if(arr[nr][nc]==-1){
                        ans = min(ans,step);
                    }else{
                        visited[nr][nc] = 1;
