void dfs(TreeNode* root, int& ans, int high, int low){
    if (root==NULL)return;
    if (root->left)dfs(root->left,ans,high,low);
    if (root->val>= low && root->val <= high)ans+=root->val;
    if (root->right)dfs(root->right,ans,high,low);
}
    int rangeSumBST(TreeNode* root, int low, int high) {
