class Solution {
    public boolean validateStackSequences(int[] pushed, int[] popped) {
        int i = 0; // Intialise one pointer pointing on pushed array
        int j = 0; // Intialise one pointer pointing on popped array

        for(int val : pushed){
            pushed[i++] = val; // using pushed as the stack.
            while(i > 0 && pushed[i - 1] == popped[j]){ // pushed[i - 1] values equal to popped[j];
                i--; // decrement i
                j++; // increment j
            }
        }
        return i == 0; // Since pushed is a permutation of popped so at the end we are supposed to be left with an empty stack
    }
},3,https://leetcode.com/problems/validate-stack-sequences,https://leetcode.com/problems/validate-stack-sequences/solutions/1853250/java-c-space-complexity-going-from-o-n-o-1/

class Solution {

    // this question is of finding the number of connected component
    // just find the number of connected component using DFS/BFS or
    // using DSU 
    // your answer will be number of stones - number of connected component because from each connected component you can pick each and every stone except the last one.

    static ArrayList<Integer> graph[];

    static void addEdge(int a, int b){
        graph[a].add(b);
        graph[b].add(a);
    }

    static void bfs(int src, int visited[]){
        Queue<Integer> q = new LinkedList<>();
        q.add(src);
        visited[src] = 1;

        while(q.size()!=0){
            int a = q.remove();
            visited[a] = 1;
            for(var x : graph[a]){
                if(visited[x]!=1){
                    visited[x]=1;
                    q.add(x);
                }
            }
        }
    }

    public int removeStones(int[][] arr) {


        int v = arr.length;

        graph = new ArrayList[v];
        for(int i=0; i<v; i++){
            graph[i] = new ArrayList<>();
        }

        for(int i=0; i<v; i++){
            int x1 = arr[i][0];
            int y1 = arr[i][1];
            for(int j=i+1; j<v; j++){
                int x2 = arr[j][0];
                int y2 = arr[j][1];

                if(x1==x2 || y1==y2){
                    addEdge(i,j);
                } 
            }
        }

        int visited[] = new int[v];
        Arrays.fill(visited,-1);
        int connected = 0;
        for(int i=0; i<v; i++){
            if(visited[i]!=1){
                connected++;
                bfs(i,visited);
            }
        }
        return v-connected;
    }
