class Solution {
public:
    int dp[21][5001];
    int fun(int idx, int n, int sum1, int sum2 , int maxSum, vector<int>& rods){
        //if the sum exceeds the maxSum we it is impossible to make both rods equal in the future
        if(sum1 > maxSum or sum2 > maxSum) return INT_MIN;

        if(idx >= n) {
            //if length of both the rods are same then return the sum1 or sum2
            return sum1 == sum2 ? sum1 : INT_MIN;
        }

        /*if we have previously reached idx with abs(sum1 - sum2) we can at max increase 
        the size of larger rod by dp[idx][abs(sum1 - sum2)]*/
        if(dp[idx][abs(sum1 - sum2)] != -1){
            return dp[idx][abs(sum1 - sum2)] == INT_MIN ? INT_MIN : dp[idx][abs(sum1 - sum2)] + max(sum1, sum2);
        }

        //we have three options at current index 
        // 1 : We add the length of the rod at idx to sum1
        // 2 : We add the length of the rod at idx to sum2
        // 3 : We do not take the rod at idx and move on to idx+1
        int op1 = fun(idx+1, n, sum1, sum2, maxSum, rods);
        int op2 = fun(idx+1, n, sum1+rods[idx] , sum2, maxSum, rods);
        int op3 = fun(idx+1, n, sum1, sum2+rods[idx], maxSum, rods);

        if(max(op1, max(op2, op3)) == INT_MIN) return dp[idx][abs(sum1 - sum2)] = INT_MIN;
        dp[idx][abs(sum1 - sum2)] = max(op1, max(op2, op3)) - max(sum1, sum2);
        return dp[idx][abs(sum1 - sum2)] + max(sum1, sum2);
    }
    int tallestBillboard(vector<int>& rods) {
        int n = rods.size();
        memset(dp, -1, sizeof(dp));
        int maxSum = accumulate(rods.begin(), rods.end(), 0) / 2;
        return max(0, fun(0, n, 0, 0, maxSum, rods));
    }
};,109,https://leetcode.com/problems/tallest-billboard,https://leetcode.com/problems/tallest-billboard/solutions/3675570/daily-leetcode-solution-easy-c-solution/

class Solution {
public:
    void makeset(int &a,vector<int> &p,vector<int> &s){
        p[a] = a;
        s[a] = 1;
    }
    int find1(int u,vector<int> &p){
        if(p[u] == u)
            return u;
        return p[u] = find1(p[u],p);
    }
    void union1(int u,int v,vector<int> &p,vector<int> &s){
        int a = find1(u,p);
        int b = find1(v,p);
        if(a!=b){
            if(s[a]<s[b])
                swap(a,b);
            p[b] = a;
            s[a] += s[b];
        }
    }
    int regionsBySlashes(vector<string>& grid) {
        int n,m = grid.size(),i,j,ans = 1,k= 0;
        n = m+1;
        vector<int> p(n*n+1),s(n*n+1);
        for(i = 0; i <= n*n; i++){
            makeset(k,p,s);
            k++;
        }
        k= 0;
        for(i = 0; i < n; i++){
            for(j = 0; j < n; j++){
                if(i==0||j==0||i==n-1||j==n-1){
                    union1(k,0,p,s);

                }
                k++;
            }
        }
        for(i = 0; i < m; i++){
            for(j = 0; j < m; j++){
                if(grid[i][j] == '/'){
                    if(find1((i+1)*n+j,p)==find1(i*n+j+1,p)){
                        ans++;
                    }
                    union1((i+1)*n+j,i*n+j+1,p,s);
                }else if(grid[i][j] == '\\'){
                    if(find1((i)*n+j,p)==find1((i+1)*n+j+1,p)){
                        ans++;
                    }
                    union1((i)*n+j,(i+1)*n+j+1,p,s);
                }
            }
        }
        return ans;
    }
};,154,https://leetcode.com/problems/regions-cut-by-slashes,https://leetcode.com/problems/regions-cut-by-slashes/solutions/2614140/time-and-space-75-beats-simple-easy-c-union-find/

