class Solution {
public:
    int shortestPathBinaryMatrix(vector<vector<int>>& grid) {
        int m=grid.size(),n=grid[0].size();
        if(grid[0][0] != 0) return -1;
        vector<vector<int>> dist(m,vector<int>(n,INT_MAX));
        dist[0][0]=1;
        priority_queue<pair<int,pair<int,int>>,vector<pair<int,pair<int,int>>>,greater<pair<int,pair<int,int>>>> pq;
        pq.push({1,{0,0}});
        while(!pq.empty()){
            auto top=pq.top();
            int row=top.second.first;
            int col=top.second.second;
            int dis=top.first;
            pq.pop();
            if(row==m-1 and col==n-1) return dis;  
            for(int i=0;i<8;i++){
                int nrow=row+delRow[i];
                int ncol=col+delCol[i];
                if(nrow>=0 and nrow<m and ncol>=0 and ncol<n and grid[nrow][ncol]==0 and dist[nrow][ncol]>dis+1){
                    dist[nrow][ncol]=dis+1;
                    pq.push({dis+1,{nrow,ncol}});
                }
            }
        }
        return -1;
    }
};,109,https://leetcode.com/problems/shortest-path-in-binary-matrix,https://leetcode.com/problems/shortest-path-in-binary-matrix/solutions/3584232/daily-leetcode-solution-bfs-easy-to-understand/

class Solution {
public:
    vector<int> corpFlightBookings(vector<vector<int>>& bookings, int n) {
        vector<int>arr(n);
        for(auto b:bookings){
            int first = b[0]-1, last = b[1], seats = b[2];
            arr[first] += seats;
            if(last == n) continue;
            arr[last] -= seats;
        }
        for(int i=1; i<n; i++){
            arr[i] += arr[i-1];
        }
        return arr;
    }
