class Solution {
public:
    vector<TreeNode*> ans;
    unordered_map<int,bool> mp;

    void solve(TreeNode* root,TreeNode* prev)
    {
         if(!root) return ;
         TreeNode* lft = root->left;
         TreeNode* rgt = root->right;
         if(mp.find(root->val)!=mp.end())
         {
             if(prev!=NULL)
             {
                 if(prev->left==root) prev->left = NULL;
                 else if(prev->right==root) prev->right = NULL;
             }
            root->left = NULL;
            root->right = NULL;
            if(lft && mp.find(lft->val)==mp.end()) ans.push_back(lft);
            if(rgt && mp.find(rgt->val)==mp.end()) ans.push_back(rgt);

            solve(lft,NULL);
            solve(rgt,NULL);
         }
         else
         {
             solve(lft,root);
             solve(rgt,root);
         }
    }
    vector<TreeNode*> delNodes(TreeNode* root, vector<int>& to_delete) {
         for(auto x : to_delete) mp[x] = 1;
         if(mp.find(root->val)==mp.end()) ans.push_back(root);
         solve(root,NULL);
         return ans;
    }
};,91,https://leetcode.com/problems/delete-nodes-and-return-forest,https://leetcode.com/problems/delete-nodes-and-return-forest/solutions/4201816/clean-c-code-beats-100/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<TreeNode*> ans;

    TreeNode* solve(TreeNode* r,unordered_map<int, int > &mp)
    {
        if(!r)
            return NULL;

        r->left = solve(r->left,mp);
        r->right = solve(r->right,mp);

        if(mp.find(r->val)!=mp.end())
        {
            if(r->left)
            {
                ans.push_back(r->left);
            }

            if(r->right)
            {
                ans.push_back(r->right);
            }

            return nullptr;

        }

        return r;
    }

    vector<TreeNode*> delNodes(TreeNode* r, vector<int>& a) {

        unordered_map<int, int > mp;
        for(auto i: a)
        {
            mp[i] = 0;
        }


        solve(r,mp);
        if(mp.find(r->val)==mp.end())
        {
            ans.push_back(r);
        }

        return ans;
    }
};,103,https://leetcode.com/problems/delete-nodes-and-return-forest,https://leetcode.com/problems/delete-nodes-and-return-forest/solutions/3816684/modifies-post-order-traversal/

