class Solution {
public:
    int numEquivDominoPairs(vector<vector<int>>& dominoes) {
        map<pair<int, int>, int> mp;
        for (auto& d : dominoes) {
            if (d[0] > d[1]) 
                swap(d[0], d[1]); // We swap the numbers so that [1,2] and [2,1] can be counted together as [1,2]
            mp[{d[0], d[1]}]++;
        }
        int ans = 0;
        for (auto& m : mp)
            ans += m.second * (m.second - 1) / 2; // Formula for sum of first n-1 numbers
        return ans;
    }
