class Solution {


    static int helper(int n, int dp[]){
        if(n==0) return dp[n]=0;
        if(n==1) return dp[n]=1;
        if(n==2) return dp[n]=1;

        if(dp[n]!=-1) return dp[n];
        else return dp[n] = helper(n-1,dp)+helper(n-2,dp)+helper(n-3,dp);
    }
    public int tribonacci(int n) {
        int dp[] = new int[n+1];
        Arrays.fill(dp,-1);
        return helper(n,dp);
    }
