class Solution {
public:
    vector<vector<vector<int>>> dp;
    int fun(int idx,int m,int turn,int n,vector<int>& piles){
        if(idx==n) return 0;
        if(dp[idx][m][turn] != -1) return dp[idx][m][turn];
        if(turn){
            int res=0,sum=0;
            for(int i=idx;i<idx+2*m and i<n;i++){
                sum+=piles[i];
                res=max(sum+fun(i+1,max(m,i-idx+1),0,n,piles),res);
            }
            return dp[idx][m][turn]=res;
        }
        else{
            int res=INT_MAX;
            for(int i=idx;i<idx+2*m and i<n;i++){
                res=min(fun(i+1,max(m,i-idx+1),1,n,piles),res);
            }
            return dp[idx][m][turn]=res;
        }
    }
    int stoneGameII(vector<int>& piles){
        int n=piles.size();
        dp=vector<vector<vector<int>>> (n,vector<vector<int>>(n+2,vector<int>(2,-1)));
        return fun(0,1,1,n,piles);
    }
