        for(int i = 0; i < indices.length; i++) {
            rowIndex = indices[i][0];
            colIndex = indices[i][1];
            for(int j = 0; j < n; j++) {
                arr[rowIndex][j] += 1;
            }
            for(int j = 0; j < m; j++) {
                arr[j][colIndex] += 1;
            }
        }

        int count = 0;
        for(int i = 0; i < m; i++) {
            for(int j = 0; j < n; j++) {
                if(arr[i][j] % 2 != 0) {
                    count++;
                }
            }
        }
        return count;
    }
