var minTimeToVisitAllPoints = function(points) {
    let a = points[0][0];
    let b = points[0][1];
    let res = 0;
    for(let i=1; i<points.length; i++) {
        let maxa = Math.abs(a - points[i][0]);
        let maxb = Math.abs(b - points[i][1]);
        res = res + Math.max(maxa, maxb);
        a = points[i][0];
        b = points[i][1];
    }
    return res;
