class Solution {
    public int countSquares(int[][] matrix) {
        int rows = matrix.length, cols = matrix[0].length;
        int[][] dp = new int[Math.min(rows, cols)][rows * cols];
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (matrix[i][j] == 1) {
                    dp[0][i * cols + j] = 1;
                    count++;
                }
            }
        }
        if(count == 0) return count;
        for (int i = 0; i < dp.length - 1; i++) {
            int levelCount = 0;
            int index = 0;
            for (int k = 0; k < rows - 1; k++) {
                for (int l = 0; l < cols - 1; l++) {
                    int j = k * cols + l;
                    if (dp[i][j] == 1 && dp[i][j + 1] == 1 && dp[i][cols + j] == 1 && dp[i][cols + j + 1] == 1) {
                        dp[i + 1][index] = 1;
                        levelCount++;
                    }
                    index++;
                }
            }
            if(levelCount == 0) break;
            count += levelCount;
            rows--;
            cols--;
        }
        return count;
    }
