class CombinationIterator {
    private final List<String> combinations;
    private int index;

    public CombinationIterator(final String characters, final int combinationLength) {
        this.combinations = new ArrayList<>();
        this.backTrack(characters, 0, combinationLength, new StringBuilder());
        this.index = 0;
    }

    public String next() {
        return this.combinations.get(this.index++);
    }

    public boolean hasNext() {
        return index < this.combinations.size();
    }

    private void backTrack(final String s, final int start, final int n, final StringBuilder sb) {
        if(sb.length() == n) {
            this.combinations.add(sb.toString());
        } else {
            for(int i = start; i < s.length(); ++i) {
                sb.append(s.charAt(i));
                backTrack(s, i + 1, n, sb);
                sb.deleteCharAt(sb.length() - 1);
            }
        }
    }
}

