class CombinationIterator {
    string s;
    int n, L;
    set<string> comb;
    set<string>::iterator cur;

    void generate(string& s, int n) {
        for(int mask = 0; mask < 1 << L; mask++) {         // iterate mask from [0, 2^L)
            if(__builtin_popcount(mask) != n) continue;    // only mask with number of set bits = n must be considered
            string combination = "";
            for(int j = 0; j < L; j++)                     // traverse over bits of current mask
                if(mask & 1 << j)                          // if jth bit is set, then
                    combination += s[j];                   // push jth character of s
            comb.insert(move(combination));                // insert the constructed string into set
        }
        cur = begin(comb);
    }
public:
    CombinationIterator(string& s, int n) : s(s), n(n), L(size(s)) { generate(s, n); }

    string next()  { return *cur++; }                      // return increment to iterator next string
    bool hasNext() { return cur != end(comb); }         // check if all strings are iterated
};,63,https://leetcode.com/problems/iterator-for-combination,https://leetcode.com/problems/iterator-for-combination/solutions/1576856/all-5-solutions-w-detailed-explanations-bitmask-backtrack-on-the-fly-gosper-s-hack/

class CombinationIterator {
    string s;
    int n, L, mask;
public:
    CombinationIterator(string s, int n) : s(s), L(size(s)), n(n), mask((1<<L) - 1) { }
    string next() {
        if(!hasNext()) return "";                 // updates mask to next lower integer having n set bits
        string combination = "";
        for(int j = L-1; j >= 0; j--)             // iterate over mask from MSB to LSB
                if(mask & 1 << j)                 // if a bit is set,
                    combination += s[L-1-j];      // then add character corresponding to that bit
        mask--;                                   // move to next mask
        return combination;
    }
    bool hasNext() {
		// checks if another mask with n set bits exists before we reach mask=0
        while(mask >= 0 && __builtin_popcount(mask) != n) mask--; 
        return mask >= 0;
    }
};,63,https://leetcode.com/problems/iterator-for-combination,https://leetcode.com/problems/iterator-for-combination/solutions/1576856/all-5-solutions-w-detailed-explanations-bitmask-backtrack-on-the-fly-gosper-s-hack/

class Solution {
    public List<Integer> sequentialDigits(int low, int high) {
        int start = 1, cur = 1, inc = 11, t = 8;
        List<Integer> ans = new ArrayList<>();
        while(cur <= high){
            for (int i = 0; i < t; i++){
                cur += inc;
                if (cur >= low && cur <= high) ans.add(cur);
            }
            inc = 10 * inc + 1;
            start = 10 * start + 10 - t;
            cur = start;
            t--;
        }

        return ans;
    }
