var findLucky = function(arr) {
    arr = arr.sort((a,b) => a - b);
    let outputs = [{value: arr[0], count: 1}];

    for (let i = 1; i < arr.length; i++) {
        const last = outputs[outputs.length - 1];
        if (last && arr[i] === last.value) {
            last.count++;
            if (last.count > last.value) {
                outputs.pop();
                while(arr[i+1] === last.value) i++;
            }
        } else {
            if (last && last.count !== last.value) {
                outputs.pop();
            }
            outputs.push({value: arr[i], count: 1});
        }
    }

    const last = outputs[outputs.length - 1];
    if (last && last.count === last.value) {
        return last.value;
    } else {
        outputs.pop();
    }

    return outputs[outputs.length - 1]?.value || -1;
