class Solution {
public:
    int maxScore(vector<int>& cardPoints, int k) {
        int n = cardPoints.size();
        int curScore = 0;
        for (int i = 0; i < k; i++)
            curScore += cardPoints[i];
        int finalScore = curScore;
        for (int i = k-1; i >= 0; i--) {
            curScore -= cardPoints[i];
            curScore += cardPoints[n-k+i];
            finalScore = max (finalScore, curScore);
        }
        return finalScore;
    }
};
