class Solution {
public:
    int numPoints(vector<vector<int>>& p, int r) {
        int n = p.size();
        vector<vector<double>> dist(n, vector<double>(n));
        for (int i=0; i<n; ++i) {
            for (int j=0; j<n; ++j) {
                dist[i][j] = dist[j][i] = sqrt((p[i][0] - p[j][0]) * (p[i][0] - p[j][0]) + (p[i][1] - p[j][1]) * (p[i][1] - p[j][1]));
            }
        }

        int res = 1;
        for (int i=0; i<n; ++i) {
            vector<pair<double, bool>> angles;

            for (int j=0; j<n; ++j) {
                if (j != i && dist[i][j] <= 2 * r) {
                    double A = atan2(p[j][1] - p[i][1], p[j][0] - p[i][0]);
                    double B = acos(dist[i][j] / (2.0 * r));
                    double alpha = A-B; 
                    double beta = A+B; 
                    angles.push_back(make_pair(alpha, false)); 
                    angles.push_back(make_pair(beta, true)); 
                }
            }

            sort(angles.begin(), angles.end());  

            int cnt = 1;
            for (auto it=angles.begin(); it!=angles.end(); ++it) 
            { 
                if ((*it).second == false) cnt++;   
                else cnt--; 

                res = max(res, cnt);
            } 
        }
        return res;
    }
};,57,https://leetcode.com/problems/maximum-number-of-darts-inside-of-a-circular-dartboard,https://leetcode.com/problems/maximum-number-of-darts-inside-of-a-circular-dartboard/solutions/2840925/c-easy-fast/

class Solution {

    /*
        Time Complexity : O(N)
        Space Complexity : O(1)
    */

private:
    bool isVowel(char ch){
        if(ch=='a' || ch=='e' || ch=='i' || ch=='o' || ch=='u')
            return true;

        return false;
    }
public:
    int maxVowels(string s, int k) {
        int res = 0, count = 0, n = s.length();

        for(int i=0; i<k; i++){
            if(isVowel(s[i])) count++;
        }

        res = max(res, count);

        for(int i=k; i<n; i++){
            int addIdx = i;
            int rmvIdx = i-k;

            if(isVowel(s[rmvIdx])) count--;
            if(isVowel(s[addIdx])) count++;

            res = max(res, count);
        }

        return res;
    }
};,68,https://leetcode.com/problems/maximum-number-of-vowels-in-a-substring-of-given-length,https://leetcode.com/problems/maximum-number-of-vowels-in-a-substring-of-given-length/solutions/3762439/c-using-sliding-window-t-c-o-n-s-c-o-1/

class Solution {
    int ans = 0;
    public int pseudoPalindromicPaths (TreeNode root) {
        ans = 0;
        dfs(root, 0);
        return ans;
    }
    private void dfs(TreeNode root, int count) {
        if (root == null) return;
        count ^= 1 << (root.val - 1);
        dfs(root.left, count);
        dfs(root.right, count);
        if (root.left == null && root.right ==  null && (count & (count - 1)) == 0) ans++;
    }
