class Solution {
public:
    int longestSubarray(vector<int>& nums) {
        int n = nums.size(),i = 0,j = 0,count_before_0 = 0,count_after_0 = 0,maxi = 0;
        while(j < n){
            if(nums[j] == 0){
                maxi = max(maxi,count_before_0 + count_after_0);
                count_before_0 = count_after_0;
                count_after_0 = 0;
            }
            else
                count_after_0 ++;
            j++;
        }
        maxi = max(maxi,count_before_0 + count_after_0);
        return maxi != n ? maxi : maxi - 1;
    }
