class Solution {
public:
    bool canArrange(vector<int>& arr, int k) {
        int n = arr.size();
        vector<int> remainders(k);
        for (int i = 0; i < n; ++i) {
            int remainder = arr[i] % k;
            if (remainder < 0) {
                remainder += k;
            }
            ++remainders[remainder];
        }
        if (remainders[0] % 2 == 1) {
            return false;
        }
        for (int i = 1; i <= k / 2; ++i) {
            if (remainders[i] != remainders[k - i]) {
                return false;
            }
        }
        return true;
    }
};,190,https://leetcode.com/problems/check-if-array-pairs-are-divisible-by-k,https://leetcode.com/problems/check-if-array-pairs-are-divisible-by-k/solutions/3114858/c-solution-beats-95-w-explanation/

class Solution {
    public boolean canMakeArithmeticProgression(int[] arr) {
        Arrays.sort(arr); // Sort the array in ascending order

        int diff = arr[1] - arr[0]; // Calculate the initial difference

        // Check if the difference between any two consecutive elements is the same
        for (int i = 2; i < arr.length; i++) {
            if (arr[i] - arr[i - 1] != diff) {
                return false; // Difference is not the same, array cannot form an arithmetic progression
            }
        }

        return true; // All differences are the same, array can form an arithmetic progression
    }
