class Solution {
public:
    int longestAwesome(string s) {
        unordered_map<int, int> m; //{mask, idx}
        m[0] = -1;

        int ans = 0;
        int state = 0;
        for(int i = 0; i < s.length(); i++) {
            int mask = (1 << (s[i] - '0'));
            state ^= mask;

            if(m.find(state) != m.end()) {
                int j = m[state];
                ans = max(ans, i - j);
            }

            for(int odd = 0; odd < 10; odd++) {
                mask = (1 << odd);
                if(m.find(state ^ mask) != m.end()) {
                    int j = m[state ^ mask];
                    ans = max(ans, i - j);
                }
            }

            // to maximize length add occurrence mask only once
            // if we add a occurrence mask twice it will update the key's previous value leading to inaccurate result 
            if(m.find(state) == m.end()) {
                m[state] = i;
            }
        }

        return ans;
    }
