/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public boolean isEvenOddTree(TreeNode root) {
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int level = 0; // Notes the Current level at which i'm standing....

// BFS Level-order Traversal...
        while(!queue.isEmpty()){
            int size = queue.size();

            TreeNode prev = null; // keeping track of prev Node..
            for(int i=0; i<size; i++){

// Even-Odd Level Check....
                if(level%2==0){ 
                // Even level
                // reject if even
                    if(queue.peek().val%2==0) return false;

                // reject if DECREASING
                    if(prev != null && prev.val >= queue.peek().val) return false;
                } else{ 
                // Odd level
                // reject if odd
                    if(queue.peek().val%2 != 0) return false;

                // reject if INCREASING
                    if(prev != null && prev.val <= queue.peek().val) return false;
                }

                prev = queue.peek();

            // adding next level nodes for the checking...
                if(queue.peek().left != null) queue.offer(queue.peek().left);
                if(queue.peek().right != null) queue.offer(queue.peek().right);

                queue.poll(); // remove the peek() node....
            }
            level++;
        }

        return true;
    }
