class Solution {
public:
    int maximalNetworkRank(int n, vector<vector<int>>& roads) {
        vector<bitset<101>> adj(n);
        vector<int> deg(n, 0);
        for (auto& edge: roads){
            int v=edge[0], w=edge[1];
            deg[v]++;
            deg[w]++;
            adj[v][w]=adj[w][v]=1;
        }

        //Supposed that this graph is connected
        int deg_max=*max_element(deg.begin(), deg.end());
        vector<int> i_max; //some graph has more vertices with max deg
        for(int i=0; i<n; i++)
            if(deg[i]==deg_max) i_max.push_back(i);
        int s_deg=i_max.size();

    //    cout<<"i_max.size="<<s_deg<<endl;
        if (s_deg>1){
            for (int i=1; i<s_deg; i++){
                for (int j=0; j<i; j++)
                    if (adj[i_max[i]][i_max[j]]==0) //no edge between
                        return 2*deg_max;
            }
            return 2*deg_max-1;//all vertices with max deg have edges mutual
        }
        //The following deals with the case s_deg=1. i.e. only one max deg
        int i_max0=i_max[0];
        int max_rank=0;
        //Find the max_rank by considering 
        //rank=deg_max+deg[j]-adj[i_max0][j]
        for(int j=0; j<n; j++){
            if (j==i_max0) continue;
            int rank=deg_max+deg[j]-adj[i_max0][j];
        //    cout<<rank<<endl;
            max_rank=max(max_rank, rank);
        }
        return max_rank;
    }
};,49,https://leetcode.com/problems/maximal-network-rank,https://leetcode.com/problems/maximal-network-rank/solutions/3924728/c-python-adjacent-matrix-and-degree-array-o-v-e/

