class Solution {
public:
    bool ispal(string s)
    {
        int i=0,j=s.size()-1;
        while(i<j)
        {
            if(s[i]!=s[j])
                return 0;
            i++;
            j--;
        }
        return 1;
    }
    bool solve(string a,string b)
    {
        int n=a.size(),m=b.size();
        int i=0,j=m-1;
        while(i<j && a[i]==b[j])
        {
            i++;
            j--;
        }
        if(ispal(a.substr(i,j-i+1)) | ispal(b.substr(i,j-i+1)))
            return 1;
        return 0;
    }
    bool checkPalindromeFormation(string a, string b)
    {
        int yes=solve(a,b)|solve(b,a);
        return yes;
    }
};
