class disjointset{
    public:
    vector<int>p;
    disjointset(int n){
        p.resize(n+1);
        for(int i=0; i<=n; i++){
            p[i]=i;
        }
    }
    int findp(int u){
        if(u==p[u]){
            return u;
        }
        return p[u]=findp(p[u]);
    }
    void un(int u, int v){
        p[findp(u)]=p[findp(v)];
    }
};
class Solution {
public:
    vector<bool> areConnected(int n, int threshold, vector<vector<int>>& queries) {
        disjointset d(n+1);
        vector<bool>ans;
