            for(int j=i; j<=n; j+=i){
                d.un(i, j);
            }
        }
        for(int i=0; i<queries.size(); i++){
            if(d.findp(queries[i][0])==d.findp(queries[i][1])){
                ans.push_back(true);
            }
            else{
                ans.push_back(false);
            }
        }
        return ans;
    }
