class Solution {
public:
    int find(vector<int> &par,int u)
    {
        if(u==par[u])
            return u;
        return par[u]=find(par,par[u]);
    }
    void unions(vector<int> &par,int u,int v)
    {
        int pu=find(par,u),pv=find(par,v);
        par[pu]=pv;
    }
    vector<bool> areConnected(int n, int threshold, vector<vector<int>>& queries) 
    {
        vector<int> par(n+1);
        for(int i=0;i<=n;i++)
        {
            par[i]=i;
        }
        for(int i=1;i<=n;i++)
        {
            for(int j=threshold+1;2*j<=i;j++)
            {
                if(i%j==0)
                {
                    unions(par,i,j);
                }
            }
        }
        vector<bool> ans;
        for(auto &q:queries)
        {
            int u=q[0],v=q[1];
            if(find(par,u)!=find(par,v))
                ans.push_back(0);
            else
                ans.push_back(1);
        }
        return ans;

    }
};
