//Greedy & Union Find
class UnionFind {    
    vector<int> root, rank;
public:
    UnionFind(int n) : root(n), rank(n) {
        rank.assign(n, 1);
        iota(root.begin(), root.end(), 0);
    }

    int Find(int x) {
        if (x == root[x]) return x;
        else return root[x] = Find(root[x]);
    }

    void Union(int x, int y) {
        int rX = Find(x), rY = Find(y);
        if (rX == rY)  return;
        if (rank[rX] > rank[rY]) swap(rX, rY);   
        root[rX] = rY;
        if (rank[rX]==rank[rY]) rank[rY]++;
    }
};
class Solution {
public:
    using int3=tuple<int, int, int>; // (wt, v, w)
    int n, m;
    int to1D(int i, int j){
        return i*m+j;
    }
    
    int minimumEffortPath(vector<vector<int>>& heights) {
        n=heights.size(), m=heights[0].size();
        if (n==1 && m==1) return 0;// edge case

        //Build edges (wt, v, w)
        vector<int3> edges;
        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                if (i<n-1){
                    int&& wt=abs(heights[i][j]-heights[i+1][j]);
                    edges.emplace_back(wt, to1D(i, j), to1D(i+1, j));
                }
                if (j<m-1){
                    int&& wt=abs(heights[i][j]-heights[i][j+1]);
                    edges.emplace_back(wt, to1D(i, j), to1D(i, j+1));
                }
            }
        }
        sort(edges.begin(), edges.end());
        int V=n*m;
        UnionFind uf(V);
        for(auto& [wt, v, w]: edges){
            if (uf.Find(v)!=uf.Find(w))
                uf.Union(v, w);
            if (uf.Find(0)==uf.Find(n*m-1))
                return wt;
        }
        return 0;
    }
