class Solution {
    public int countVowelStrings(int n) {
        // 0=a, 1=e, 2=i, 3=o, 4=u
        int[] dp = new int[5];

        Arrays.fill(dp, 1);
        int prevSum = 5;

        for(int i=1; i<n; i++){

            int newSum = prevSum;
            int prev = dp[0];
            dp[0] = prevSum; 

            for(int v=1; v<5; v++){
                int temp = dp[v];
                dp[v] = dp[v-1] - prev;
                newSum += dp[v];
                prev = temp;
            }
            prevSum = newSum;
        }
        return prevSum;
    }
