class Solution {
    public double averageWaitingTime(int[][] customers) {
        double total_wait_time=(customers[0][0]+customers[0][1])-customers[0][0];
        customers[0][1]=customers[0][0]+customers[0][1];
        for(int i=1; i<customers.length; i++){
            double temp=customers[i][0];
            customers[i][0]=Math.max(customers[i][0],customers[i-1][1]);
            customers[i][1]=customers[i][0]+customers[i][1];
            total_wait_time+=customers[i][1]-temp;
        }
        return total_wait_time/customers.length;
    }
}
