var eatenApples = function (apples, days) {
  let n = apples.length;
  let maxApplesEaten = 0;

  let minHeap = new PriorityQueue({ compare: (a, b) => a.expiryDate - b.expiryDate });

  // 4e4 is (last element + expiry) from question
  for (let daysPassed = 0; daysPassed <= 4e4; daysPassed++) {
    if (daysPassed < n) {
      // loop thru  until  all days is completed
      minHeap.enqueue({ appleCount: apples[daysPassed], expiryDate: daysPassed + days[daysPassed] });
    } else {
      // later, until some  possibly non expiry/ appl exists
      if (minHeap.isEmpty()) break;
    }

    // remove expired elements,  no apple days
    while (!minHeap.isEmpty()) {
      let { appleCount, expiryDate } = minHeap.front();
      if (expiryDate <= daysPassed || appleCount === 0) minHeap.dequeue();
      else break;
    }
    // reduce apple count  of non-expired day
    if (!minHeap.isEmpty()) {
      let { appleCount, expiryDate } = minHeap.dequeue();
      minHeap.enqueue({ appleCount: appleCount - 1, expiryDate });
      maxApplesEaten++;
    }
  }

  return maxApplesEaten;
};,100,https://leetcode.com/problems/maximum-number-of-eaten-apples,https://leetcode.com/problems/maximum-number-of-eaten-apples/solutions/4216842/javascript-1705-maximum-number-of-eaten-apples/

