class Solution {
public:
    int largestSubmatrix(vector<vector<int>>& matrix) {
        int m = matrix.size();  // Number of rows in the matrix
        int n = matrix[0].size();  // Number of columns in the matrix
        vector<pair<int,int>> prevHeights;  // To store heights of 1s from the previous row
        int ans = 0;  // Initialize the maximum submatrix area

        for (int row = 0; row < m; row++) {
            vector<pair<int,int>> heights;  // Heights of 1s for the current row
            vector<bool> seen = vector(n, false);  // To track the columns already seen

            // Process the heights from the previous row
            for (auto [height, col] : prevHeights) {
                if (matrix[row][col] == 1) {
                    heights.push_back({height + 1, col});  // Increase the height if the current element is 1
                    seen[col] = true;  // Mark the column as seen
                }
            }

            // Process the new heights in the current row
            for (int col = 0; col < n; col++) {
                if (seen[col] == false && matrix[row][col] == 1) {
                    heights.push_back({1, col});  // New height for a new column
                }
            }

            // Calculate the area for each height and update the maximum area
            for (int i = 0; i < heights.size(); i++) {
                ans = max(ans, heights[i].first * (i + 1));
            }

            prevHeights = heights;  // Update the heights for the next row
        }

        return ans;  // Return the maximum submatrix area
    }
};


